files.content:
* {
  box-sizing: border-box;
}

html {
  height: 100vh;
}

body {
  min-width: 850px;
  min-height: 100vh;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.hero {
  display: grid;
  place-items: center;
  padding-inline: 25px;
  padding-block-start: 25px;
  padding-block-end: 100px;
  background-color: #fd24af;
}

.hero-title {
  width: 90%;
  max-width: 550px;
  font-weight: 800;
  font-size: 45px;
  text-transform: uppercase;
}

.hero-image {
  width: 250px;
  height: 250px;
  mask-image: url(../svg/mask.svg);
}
